Saving Search

import { test, expect } from '@playwright/test';

test('test', async ({ page }) => {
  await page.locator('#top-open-search-panel').click();
  await page.locator('#client').fill('the');
  await page.getByRole('option', { name: 'The Bluth Company', exact: true }).click();
  await page.locator('a').filter({ hasText: 'Status' }).click();
  await page.locator('#p-multiselect-status').getByText('Choose').click();
  await page.getByText('Active', { exact: true }).click();
  await page.getByRole('button', { name: 'Search' }).click();
  await expect(page.getByRole('button', { name: 'Save Search as Folder' })).toBeVisible();
  await page.getByRole('button', { name: 'Save Search as Folder' }).click();
  await page.locator('#ui-tabpanel-26 #new-folder-name').click();
  await page.locator('#ui-tabpanel-26 #new-folder-name').fill('Bluth');
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await expect(page.getByRole('link', { name: 'Bluth (0)' })).toBeVisible();
  await page.getByRole('link', { name: 'Bluth (0)' }).click();
  await expect(page.getByText('client: The Bluth Company')).toBeVisible();
  await expect(page.getByText('status: Active')).toBeVisible();
});

 

