  await page.locator('div:nth-child(45) > .ui-g > .ui-g-5 > span > i:nth-child(4)').click();
  await page.getByText('Choose').click();
  await page.getByRole('listitem', { name: 'Demo Sales Executive' }).locator('div').nth(1).click();
  await page.locator('div').filter({ hasText: /^Select who you would like to share this filter withDemo Sales Executive$/ }).first().click();
  await page.getByRole('button', { name: 'Share' }).click();
  await page.locator('#filterOptions #closeIcon').click();
  await page.locator('.arrow').first().click();
  await page.getByRole('link', { name: 'Logout' }).click();
  await page.getByRole('button', { name: 'Login' }).click();
  await page.getByRole('button', { name: 'Login' }).click();
  await expect(page.getByRole('link', { name: 'Bluth (6)' })).toBeVisible();
});










